function renderSummary(){var totals=aggregateProgress();document.getElementById("summaryMastery").textContent=(totals.practiced?Math.round(totals.masteryTotal/totals.practiced):0)+"%";document.getElementById("summaryAccuracy").textContent=(totals.attempts?Math.round(100*totals.correct/totals.attempts):0)+"%";document.getElementById("summaryAttempts").textContent=totals.attempts;}function renderCurrentMetrics(){if(!currentQuestion)return;var s=getStat(currentQuestion.familyId,currentQuestion.level);document.getElementById("questionMastery").textContent=s.mastery+"% "+t("practice.masterySuffix","mastery");document.getElementById("metricMastery").textContent=s.mastery+"%";document.getElementById("metricAccuracy").textContent=(s.attempts?Math.round(100*s.correct/s.attempts):0)+"%";document.getElementById("metricStreak").textContent=s.streak;document.getElementById("metricAvgTime").textContent=s.attempts?PracticeLabUI.formatSeconds(s.totalMs/s.attempts):"0s";}function renderPracticeControls(){var family=currentQuestion?familyById(currentQuestion.familyId):familyById(progress.manual.familyId);selectorController.render({familyId:family.id,level:currentQuestion?currentQuestion.level:progress.manual.level});document.getElementById("adaptiveModeBtn").classList.toggle("secondary-active",progress.settings.adaptive);document.getElementById("manualModeBtn").classList.toggle("secondary-active",!progress.settings.adaptive);}function setManualSelection(id,level){progress.manual.familyId=familyById(id).id;progress.manual.level=Math.max(1,Math.min(5,Number(level)||1));progress.settings.adaptive=false;saveProgress();startQuestion();}
