function setView(view){progress.view=view;saveProgress();document.querySelectorAll(".view").forEach(function(x){x.classList.toggle("active",x.id==="view-"+view);});document.querySelectorAll("[data-view]").forEach(function(x){x.classList.toggle("active",x.dataset.view===view);});if(view==="matrix")renderMatrix();if(view==="stats")renderStats();if(view==="settings")renderSettings();if(view==="learn"){renderLearn();if(learnSpotlightId){var card=document.getElementById("learn-"+learnSpotlightId);if(card)card.scrollIntoView({block:"center"});}}if(view==="practice"&&!currentQuestion)startQuestion();}function renderAll(){renderSummary();renderPracticeControls();setView(progress.view||"practice");}
